import re
import textwrap
from collections import Counter, defaultdict
from typing import Dict, List, Optional, Tuple

import viktor as vkt


def _as_str(value) -> str:
    if value is None:
        return ""
    return str(value)


def _safe_attr(obj, attr: str) -> Optional[str]:
    try:
        val = getattr(obj, attr)
    except Exception:
        return None
    if val is None:
        return None
    return str(val)


def _get_ifc_text(ifc_file: vkt.File) -> str:
    """Return IFC content as text.

    VIKTOR's uploaded file can be returned as either str or bytes, depending on platform.
    """
    raw = ifc_file.getvalue()
    if isinstance(raw, bytes):
        return raw.decode("utf-8", errors="ignore")
    return str(raw)


def _parse_additional_classes(text: str) -> List[str]:
    if not text:
        return []
    parts = [p.strip() for p in text.split(",")]
    return [p for p in parts if p]


def _get_container_label(element) -> str:
    """Try to return a useful spatial container label (storey/building/etc.)."""
    try:
        import ifcopenshell.util.element  # lazy import

        container = ifcopenshell.util.element.get_container(element)
        if not container:
            return ""
        return f"{container.is_a()}: {(_safe_attr(container, 'Name') or '').strip()}".strip()
    except Exception:
        return ""


def _get_type_label(element) -> str:
    """Try to return assigned type name (IfcTypeObject)."""
    try:
        import ifcopenshell.util.element  # lazy import

        t = ifcopenshell.util.element.get_type(element)
        if not t:
            return ""
        return f"{t.is_a()}: {(_safe_attr(t, 'Name') or '').strip()}".strip()
    except Exception:
        return ""


def _infer_suggested_class(element) -> str:
    """Heuristic suggestion: based on common Psets and name/object type keywords.

    This is intentionally conservative; it is meant as a quick hint, not a guarantee.
    """
    name = (_safe_attr(element, "Name") or "").lower()
    obj_type = (_safe_attr(element, "ObjectType") or "").lower()
    tag = (_safe_attr(element, "Tag") or "").lower()
    type_label = _get_type_label(element).lower()
    blob = " ".join([name, obj_type, tag, type_label])

    # First: Pset-based inference (often very reliable)
    try:
        import ifcopenshell.util.element

        psets = ifcopenshell.util.element.get_psets(element) or {}
        pset_names = set(psets.keys())
        pset_to_class = {
            "Pset_DoorCommon": "IfcDoor",
            "Pset_WindowCommon": "IfcWindow",
            "Pset_WallCommon": "IfcWall",
            "Pset_SlabCommon": "IfcSlab",
            "Pset_BeamCommon": "IfcBeam",
            "Pset_ColumnCommon": "IfcColumn",
            "Pset_RoofCommon": "IfcRoof",
            "Pset_StairCommon": "IfcStair",
            "Pset_CurtainWallCommon": "IfcCurtainWall",
        }
        for pset_name, ifc_class in pset_to_class.items():
            if pset_name in pset_names:
                return ifc_class
    except Exception:
        pass

    # Second: keyword-based inference
    keyword_map = [
        (r"\bdoor\b", "IfcDoor"),
        (r"\bwindow\b", "IfcWindow"),
        (r"\bwall\b", "IfcWall"),
        (r"\bslab\b|\bfloor\b", "IfcSlab"),
        (r"\bbeam\b", "IfcBeam"),
        (r"\bcolumn\b|\bcol\b", "IfcColumn"),
        (r"\broof\b", "IfcRoof"),
        (r"\bstair\b", "IfcStair"),
        (r"\brailing\b", "IfcRailing"),
        (r"\bduct\b", "IfcDuctSegment"),
        (r"\bpipe\b", "IfcPipeSegment"),
        (r"\bcable\b", "IfcCableSegment"),
        (r"\bluminaire\b|\blight\b", "IfcLightFixture"),
        (r"\bfurniture\b", "IfcFurniture"),
    ]
    for pat, ifc_class in keyword_map:
        if re.search(pat, blob, flags=re.IGNORECASE):
            return ifc_class

    return ""


def _scan_for_proxy_like_elements(
    model,
    proxy_classes: List[str],
    include_notdefined_predefinedtype: bool,
) -> Tuple[List[dict], dict]:
    """Scan IFC model and return (flagged_elements, summary).

    flagged_elements: list of dicts with stable keys used by views.
    """
    try:
        products = model.by_type("IfcProduct")
        total_products = len(products)
    except Exception:
        total_products = 0

    # STEP id -> {'element': ifc_entity, 'reasons': set(str)}
    flagged: Dict[int, dict] = {}

    def add_flag(elem, reason: str):
        step_id = int(elem.id())
        if step_id not in flagged:
            flagged[step_id] = {"element": elem, "reasons": set()}
        flagged[step_id]["reasons"].add(reason)

    # 1) Explicit proxy classes
    for cls in proxy_classes:
        try:
            for elem in model.by_type(cls):
                add_flag(elem, f"Class = {cls}")
        except Exception:
            # Ignore unknown class names for the current IFC schema.
            continue

    # 2) "Unspecified" often means PredefinedType NOTDEFINED/USERDEFINED
    if include_notdefined_predefinedtype:
        try:
            for elem in model.by_type("IfcElement"):
                pt = _safe_attr(elem, "PredefinedType")
                if pt and pt.upper() in {"NOTDEFINED", "USERDEFINED"}:
                    add_flag(elem, f"PredefinedType = {pt.upper()}")
        except Exception:
            pass

    # Build rows
    rows: List[dict] = []
    for step_id in sorted(flagged.keys()):
        elem = flagged[step_id]["element"]
        reasons = sorted(flagged[step_id]["reasons"])

        ifc_class = elem.is_a()
        global_id = _safe_attr(elem, "GlobalId")
        name = _safe_attr(elem, "Name")
        object_type = _safe_attr(elem, "ObjectType")
        tag = _safe_attr(elem, "Tag")
        predefined_type = _safe_attr(elem, "PredefinedType")
        container = _get_container_label(elem)
        type_label = _get_type_label(elem)
        suggested = _infer_suggested_class(elem)

        rows.append(
            {
                "step_id": step_id,
                "global_id": global_id or "",
                "ifc_class": ifc_class or "",
                "name": name or "",
                "object_type": object_type or "",
                "tag": tag or "",
                "predefined_type": predefined_type or "",
                "container": container or "",
                "type": type_label or "",
                "reasons": "; ".join(reasons),
                "suggested_class": suggested or "",
            }
        )

    summary = {
        "total_products": total_products,
        "flagged_count": len(rows),
    }
    return rows, summary


def _require_ifc_file(params) -> vkt.File:
    ifc_field = params.page_1.tab_1.inputs.ifc_file
    if not ifc_field:
        raise vkt.UserError("Please upload an IFC file on '1. Upload & Settings'.")
    if not getattr(ifc_field, "file", None):
        raise vkt.UserError("Please upload an IFC file on '1. Upload & Settings'.")
    return ifc_field.file


def _load_model_from_params(params):
    import ifcopenshell

    ifc_file = _require_ifc_file(params)
    ifc_text = _get_ifc_text(ifc_file)

    # Preferred: parse from string to avoid writing to disk.
    try:
        return ifcopenshell.file.from_string(ifc_text)
    except Exception as e:
        raise vkt.UserError(f"Could not parse IFC file. Details: {e}")


class Parametrization(vkt.Parametrization):
    page_1 = vkt.Page("1. Upload & Settings")
