class Controller(vkt.Controller):
    label = "Classification Check (Proxy Elements)"
    parametrization = Parametrization(width=60)

    def _get_scan_inputs(self, params) -> Tuple[List[str], bool]:
        base_proxy_classes = ["IfcBuildingElementProxy", "IfcProxy"]
        extra = _parse_additional_classes(params.page_1.tab_1.settings.additional_proxy_classes)
        # De-duplicate while keeping order
        proxy_classes = []
        for cls in base_proxy_classes + extra:
            if cls not in proxy_classes:
                proxy_classes.append(cls)
        include_notdefined = bool(params.page_1.tab_1.settings.include_notdefined)
        return proxy_classes, include_notdefined

    def _scan(self, params) -> Tuple[List[dict], dict]:
        model = _load_model_from_params(params)
        proxy_classes, include_notdefined = self._get_scan_inputs(params)
        return _scan_for_proxy_like_elements(model, proxy_classes, include_notdefined)

    @vkt.DataView("Summary", duration_guess=2)
    def summary(self, params, **kwargs) -> vkt.DataResult:
        try:
            rows, summary = self._scan(params)
        except vkt.UserError as e:
            return vkt.DataResult(vkt.DataGroup(vkt.DataItem("Upload IFC", str(e))))

        flagged_count = int(summary.get("flagged_count", 0))
        total_products = int(summary.get("total_products", 0))
        pct = (100.0 * flagged_count / total_products) if total_products else 0.0

        status = vkt.DataStatus.SUCCESS if flagged_count == 0 else vkt.DataStatus.WARNING
        status_msg = "No proxy/unspecified elements found." if flagged_count == 0 else "Review flagged elements."

        data = vkt.DataGroup(
            model=vkt.DataItem(
                "Model",
                "",
                subgroup=vkt.DataGroup(
                    vkt.DataItem("Total IfcProduct", total_products),
                ),
            ),
            flagged=vkt.DataItem(
                "Flagged elements",
                flagged_count,
                status=status,
                status_message=status_msg,
                subgroup=vkt.DataGroup(
                    vkt.DataItem("Flagged / total", round(pct, 2), suffix=" %"),
                ),
            ),
        )
        return vkt.DataResult(data)

    @vkt.TableView("Flagged elements", duration_guess=3)
    def proxy_table(self, params, **kwargs) -> vkt.TableResult:
        try:
            rows, _ = self._scan(params)
        except vkt.UserError:
            return vkt.TableResult(
                [],
                column_headers=[
                    "STEP id",
                    "GlobalId",
                    "IFC class",
                    "Name",
                    "ObjectType",
                    "Tag",
                    "PredefinedType",
                    "Container",
                    "Type",
                    "Reasons",
                    "Suggested class",
                ],
            )

        table = [
            [
                r["step_id"],
                r["global_id"],
                r["ifc_class"],
                r["name"],
                r["object_type"],
                r["tag"],
                r["predefined_type"],
                r["container"],
                r["type"],
                r["reasons"],
                r["suggested_class"],
            ]
            for r in rows
        ]

        return vkt.TableResult(
            table,
            column_headers=[
                "STEP id",
                "GlobalId",
                "IFC class",
                "Name",
                "ObjectType",
                "Tag",
                "PredefinedType",
                "Container",
                "Type",
                "Reasons",
                "Suggested class",
            ],
        )

    @vkt.TableView("Breakdown", duration_guess=2)
    def breakdown_table(self, params, **kwargs) -> vkt.TableResult:
        try:
            rows, _ = self._scan(params)
        except vkt.UserError:
            return vkt.TableResult([], column_headers=["IFC class", "Reason", "Count"])

        counts = Counter()
        for r in rows:
            ifc_class = r.get("ifc_class", "") or ""
            reasons = [x.strip() for x in (r.get("reasons", "") or "").split(";") if x.strip()]
            if not reasons:
                reasons = ["(unknown)"]
            for reason in reasons:
                counts[(ifc_class, reason)] += 1

        data = [[k[0], k[1], v] for k, v in sorted(counts.items(), key=lambda x: (-x[1], x[0][0], x[0][1]))]
        return vkt.TableResult(data, column_headers=["IFC class", "Reason", "Count"])

    @vkt.IFCAndDataView("IFC viewer", duration_guess=3, x_axis_to_right=True)
    def ifc_and_data(self, params, **kwargs) -> vkt.IFCAndDataResult:
        ifc_file = _require_ifc_file(params)

        model = _load_model_from_params(params)
        proxy_classes, include_notdefined = self._get_scan_inputs(params)
        scan_rows, _ = _scan_for_proxy_like_elements(model, proxy_classes, include_notdefined)
        flagged_reasons_by_step_id = {int(r["step_id"]): r.get("reasons", "") for r in scan_rows}

        if selected := params.page_3.tab_1.controls.geometry:
            try:
                elem = model.by_id(int(selected))
            except Exception:
                elem = None

            if not elem:
                data = vkt.DataGroup(vkt.DataItem("Selection", "Could not find element by STEP id."))
                return vkt.IFCAndDataResult(ifc=ifc_file, data=data)

            step_id = int(elem.id())
            ifc_class = elem.is_a()
            reasons = flagged_reasons_by_step_id.get(step_id, "")
            suggested = _infer_suggested_class(elem)

            # Basic attributes
            items = [
                vkt.DataItem("STEP id", step_id),
                vkt.DataItem("IFC class", ifc_class),
                vkt.DataItem("GlobalId", _safe_attr(elem, "GlobalId") or ""),
                vkt.DataItem("Name", _safe_attr(elem, "Name") or ""),
                vkt.DataItem("ObjectType", _safe_attr(elem, "ObjectType") or ""),
                vkt.DataItem("Tag", _safe_attr(elem, "Tag") or ""),
                vkt.DataItem("PredefinedType", _safe_attr(elem, "PredefinedType") or ""),
                vkt.DataItem("Container", _get_container_label(elem) or ""),
                vkt.DataItem("Type", _get_type_label(elem) or ""),
            ]

            if reasons:
                items.append(
                    vkt.DataItem(
                        "Flagged as proxy/unspecified",
                        "YES",
                        status=vkt.DataStatus.WARNING,
                        status_message=reasons,
                    )
                )
            else:
                items.append(vkt.DataItem("Flagged as proxy/unspecified", "NO", status=vkt.DataStatus.SUCCESS))

            if suggested:
                items.append(vkt.DataItem("Suggested class", suggested))

            # Property sets (limited to stay within DataView item limits)
            try:
                import ifcopenshell.util.element

                psets = ifcopenshell.util.element.get_psets(elem) or {}
                pset_items = []
                for pset_name in sorted(psets.keys())[:15]:
                    props = psets.get(pset_name) or {}
                    sub = []
                    for k in sorted(props.keys())[:10]:
                        sub.append(vkt.DataItem(_as_str(k), _as_str(props.get(k))))
                    pset_items.append(vkt.DataItem(pset_name, "", subgroup=vkt.DataGroup(*sub)))

                if pset_items:
                    items.append(vkt.DataItem("Property sets (sample)", "", subgroup=vkt.DataGroup(*pset_items)))
            except Exception:
                pass

            data = vkt.DataGroup(*items)
        else:
            data = vkt.DataGroup(vkt.DataItem("Selection", "Select an element to see details."))

        return vkt.IFCAndDataResult(ifc=ifc_file, data=data)
